#include <iostream>
#include <vector>
#include <string>
#include <queue>

using namespace std;

/**
 * Problem: 10601 - Eternal Truths
 * 
 * 解題思路：
 * 1. 迷宮最短路徑問題，使用廣度優先搜尋 (BFS)。
 * 2. 狀態定義為 (x, y, k)，其中 (x, y) 是當前座標，k 是下一次要走的步數 (k=1, 2, 3)。
 * 3. 每次移動必須走恰好 k 步，且途中不能撞牆或出界。
 * 4. 步數順序循環為 1 -> 2 -> 3 -> 1 ...
 */

struct State {
    int r, c, k, dist;
};

int main() {
    int T;
    cin >> T;
    while (T--) {
        int R, C;
        cin >> R >> C;
        vector<string> grid(R);
        int startR, startC, endR, endC;
        for (int i = 0; i < R; ++i) {
            cin >> grid[i];
            for (int j = 0; j < C; ++j) {
                if (grid[i][j] == 'S') { startR = i; startC = j; }
                if (grid[i][j] == 'E') { endR = i; endC = j; }
            }
        }

        // dist[r][c][k] 表示到達 (r,c) 且下一步要走 k 步的最短移動次數
        vector<vector<vector<int>>> dist(R, vector<vector<int>>(C, vector<int>(4, -1)));
        queue<State> q;
        q.push({startR, startC, 1, 0});
        dist[startR][startC][1] = 0;

        int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
        bool found = false;

        while (!q.empty()) {
            State curr = q.front(); q.pop();
            if (curr.r == endR && curr.c == endC) {
                cout << curr.dist << endl;
                found = true; break;
            }

            int nextK = (curr.k == 3) ? 1 : curr.k + 1;
            for (int i = 0; i < 4; ++i) {
                int nr = curr.r, nc = curr.c;
                bool ok = true;
                for (int step = 1; step <= curr.k; ++step) {
                    nr += dr[i]; nc += dc[i];
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || grid[nr][nc] == '#') {
                        ok = false; break;
                    }
                }
                if (ok && dist[nr][nc][nextK] == -1) {
                    dist[nr][nc][nextK] = curr.dist + 1;
                    q.push({nr, nc, nextK, curr.dist + 1});
                }
            }
        }
        if (!found) cout << "NO" << endl;
    }
    return 0;
}
